CREATE OR ALTER FUNCTION [utility].[GetStringWithinBrackets](
	@value nvarchar(1000),
	@startchar char(1),
	@endchar char(1)
)
RETURNS varchar(1000)
AS
BEGIN
    DECLARE @retstring varchar(1000) = @value;

	if (CHARINDEX(@startchar,@value )>0 AND CHARINDEX(@endchar,@value )>0)
	begin
		set @retstring = SUBSTRING(@value,CHARINDEX(@startchar,@value)+1,CHARINDEX(@endchar,@value) - CHARINDEX(@startchar,@value) - 1);
	end

    RETURN @retstring
END
